  if (typeof args.query !== 'string') {
    throw new Error('query must be a string');
  }

  // Validate offset
  let offset = args.offset;
  if (offset !== undefined) {
    if (!Number.isInteger(offset)) {
      throw new Error('offset must be an integer');
    }
  } else {
    offset = 0;
  }

  // Validate limit
  let limit = args.limit;
